export function batchPresented(apply: () => void): void {
  presented.batchDepth += 1;
  try {
    apply();
  } finally {
    presented.batchDepth -= 1;
    if (presented.batchDepth === 0 && presented.isChanged) {
      presented.isChanged = false;
      notifyWatchers();
    }
  }
