export function registerPresentedOffset(
  element: Element,
  source: PresentedSource,
): () => void {
  sources.set(element, source);
  notifyWatchers();
  return () => {
    if (sources.get(element) === source) {
      sources.delete(element);
      notifyWatchers();
    }
  };
