export function presentedOffsetOf(
  element: Element,
  time?: number,
): PresentedOffset {
  if (sources.size === 0) {
    return ZERO;
  }
  let x = 0;
  let y = 0;
  for (
    let node: Node | null = element;
    node != null;
    node = parentAcrossShadow(node)
  ) {
    const source = isElement(node) ? sources.get(node) : undefined;
    if (source != null) {
      const offset = source.offset(time);
      x += offset.x;
      y += offset.y;
    }
  }
  return {x, y};
