      return true;
    }
  }
  return false;
}

/** The caret position the engine puts at a point, by either query. */
export function caretAt(
  doc: Document,
  x: number,
  y: number,
  shadowRoots: ReadonlyArray<ShadowRoot>,
): {node: Node; offset: number} | null {
